#include "rtsa_trace.h"
#ifdef CONFIG_XIAOPAI_RTSA_PROBE
#include <stdio.h>
#include <unistd.h>
#endif

struct rtsa_thread_start
{
  void (*entry)(void *);
  void *arg;
};

static void *thread_entry(void *arg)
{
  struct rtsa_thread_start start = *(struct rtsa_thread_start *)arg;
  free(arg);
  start.entry(start.arg);
  return NULL;
}

int rtsa_agora_create_thread(uint32_t *handle, uint8_t priority,
                              const char *name, void (*entry)(void *),
                              uint32_t stack_size, void *arg)
{
  pthread_attr_t attr;
  pthread_t thread;
  int ret;
  (void)name;
  (void)priority;
  if (!handle) return -EINVAL;
  *handle = 0;
  if (!entry || stack_size > 65536) return -EINVAL;
  if (stack_size < 4096) stack_size = 4096;
#ifdef CONFIG_XIAOPAI_RTSA_PROBE
  printf("RTSA thread create: stack=%lu native_priority=100\n",
         (unsigned long)stack_size);
  fflush(stdout);
  usleep(20000);
#endif
  struct rtsa_thread_start *start = malloc(sizeof(*start));
  if (!start) return -ENOMEM;
  start->entry = entry; start->arg = arg;
  ret = pthread_attr_init(&attr);
  if (!ret)
    {
      ret = pthread_attr_setstacksize(&attr, stack_size);
      if (!ret) ret = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
#ifdef __NuttX__
      struct sched_param param = {.sched_priority = 100};
      if (!ret) ret = pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
      if (!ret) ret = pthread_attr_setschedpolicy(&attr, SCHED_RR);
      if (!ret) ret = pthread_attr_setschedparam(&attr, &param);
      _Static_assert(sizeof(pthread_t) == 4, "vendor thread handle ABI");
#endif
      if (!ret) ret = pthread_create(&thread, &attr, thread_entry, start);
      pthread_attr_destroy(&attr);
    }
  if (ret) free(start);
  else *handle = (uint32_t)(uintptr_t)thread;
#ifdef CONFIG_XIAOPAI_RTSA_PROBE
  printf("RTSA thread create returned: result=%d\n", -ret);
  fflush(stdout);
#endif
  return -ret;
}

uint32_t rtsa_xTaskGetCurrentTaskHandle(void)
{
  return (uint32_t)(uintptr_t)pthread_self();
}

int rtsa_rtos_delete_thread(void *handle)
{
  /* Observed SDK exit path deletes self. Do not emulate unsafe external
   * task deletion, which could abandon locks or socket ownership. */
  if (handle) return -ENOTSUP;
  RTSA_TRACE("pthread-exit", pthread_self(), 0);
  pthread_exit(NULL);
  return 0;
}

uint32_t rtsa_rtos_get_time(void)
{
  struct timespec ts;
  if (clock_gettime(CLOCK_MONOTONIC, &ts)) abort();
  return (uint32_t)((uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

int rtsa_clock_gettime(int clock, void *result)
{
  struct timespec ts;
  if (!result || (clock != 0 && clock != 1)) { errno = EINVAL; return -1; }
  int ret = clock_gettime(clock ? CLOCK_MONOTONIC : CLOCK_REALTIME, &ts);
  if (!ret)
    {
      int64_t seconds = ts.tv_sec;
      int32_t nanos = ts.tv_nsec;
      memset(result, 0, 16);
      memcpy(result, &seconds, 8);
      memcpy((char *)result + 8, &nanos, 4);
    }
  return ret;
}

int *rtsa_errno(void) { return &errno; }

